from taf.rfrl.l3_call.cell.classical_cell.classical_lte_cell import ClassicalLteCell
from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output, log_to_console
from taf.rfrl.l3_call.cell.exceptions import ParameterNotFound


class ClassicalIotCell(ClassicalLteCell):
    def __init__(self, cell_distname, bts_connection_alias, shared_spectrum):
        super(ClassicalIotCell, self).__init__(cell_distname, bts_connection_alias, shared_spectrum)
        self._type = "iot"

    def __str__(self):
        return "ClassicalIotCell cell instance for {0} cell type".format(self._type)

    def _make_uncallable(self, delta):
        log_to_console("Adding cellBarred parameter update for IoT cell {} to delta".format(self.distname))
        delta.add_parameter_to_delta(dist_name=self.distname + "/SIB-0", parameter="cellBarred",
                                     value="barred")

    @log_input_and_output
    def _get_ok_msgs_and_procedure_codes(self):
        return {
            "InitialUEMessage": 12,
            "ConnectionEstablishmentIndication": 54,
            "DownlinkNASTransport": 11,
            "UplinkNASTransport": 13
        }

    @log_input_and_output
    def _get_nok_msgs_and_procedure_codes(self):
        return {
            # Placeholder for future IoT NOK messages
        }

    def _get_narrowband_iot_mode(self, timeout=30):
        cells_info = self._api.get_cells_info(cell_type="lte", connection=self._connection, timeout=timeout)

        for cell in cells_info:
            if cell["id"]["configuration"] == self.distname:
                return cell.get('narrowbandIotMode')

        raise ParameterNotFound("Could not find narrowbandIotMode for IoT cell with confifuration distname: {}. "
                                "Please check if given configuration distname is correct!".format(self.distname))

    def _get_cell_runtime_distname(self, timeout=30):
        cells_info = self._api.get_cells_info(cell_type="lte", connection=self._connection, timeout=timeout)

        for cell in cells_info:
            if cell["id"]["configuration"] == self.distname:
                return cell["id"]["internal"]

        raise ParameterNotFound("Could not find runtime distname for IoT cell with confifuration distname: {}. "
                                "Please check if given configuration distname is correct!".format(self.distname))
